using Haitch.Roslyn.Tests.Models;
using Haitch.Roslyn.Types;
using Haitch.Roslyn.Writing;
using Microsoft.CodeAnalysis;

namespace Haitch.Roslyn.Tests.Writing;

public class SourceWriterExtensionsTests
{
    [Test]
    public async Task Should_write_the_auto_generated_header()
    {
        SourceWriter writer = new();

        writer.WriteAutoGeneratedHeader();

        string expected = """
            // <auto-generated/>
            #nullable enable


            """;

        await Assert.That(writer.ToString()).IsEqualTo(expected);

        CompilationHelper.Compile(writer.ToString());
    }

    [Test]
    public async Task Should_write_a_file_scoped_namespace_and_a_simple_type_declaration()
    {
        TypeModel model = new(
            Namespace: "Example",
            Name: "Sample",
            Kind: TypeDeclarationKind.Class,
            Accessibility: Accessibility.Public,
            IsStatic: false,
            IsAbstract: false,
            IsSealed: false,
            IsReadOnly: false,
            IsRefLikeType: false,
            IsFileLocal: false,
            TypeParameters: default,
            ContainingTypes: default,
            Attributes: default,
            Fields: default,
            Properties: default,
            Methods: default
        );

        SourceWriter writer = new();
        writer.WriteAutoGeneratedHeader();
        writer.WriteNamespace(model.Namespace);

        using (writer.WriteTypeDeclaration(model)) { }

        string expected = """
            // <auto-generated/>
            #nullable enable

            namespace Example;

            partial class Sample
            {
            }

            """;

        await Assert.That(writer.ToString()).IsEqualTo(expected);

        const string originalSource = """
            namespace Example;

            public partial class Sample
            {
            }
            """;

        // Compile only the type declaration alongside the original source: the full writer
        // output above also carries "namespace Example;", and a file can declare a file-scoped
        // namespace only once (CS8940), so a second copy from the original source would collide.
        SourceWriter typeOnlyWriter = new();
        using (typeOnlyWriter.WriteTypeDeclaration(model)) { }

        CompilationHelper.Compile(originalSource + "\n" + typeOnlyWriter.ToString());
    }

