    [Test]
    public async Task Should_write_a_partial_declaration_nested_two_levels_deep()
    {
        ContainingTypeModel outer = new(
            Kind: TypeDeclarationKind.Class,
            Name: "Outer",
            TypeParameters: default,
            Accessibility: Accessibility.Public,
            IsReadOnly: false,
            IsRefLikeType: false
        );

        ContainingTypeModel inner = new(
            Kind: TypeDeclarationKind.Struct,
            Name: "Inner",
            TypeParameters: default,
            Accessibility: Accessibility.Public,
            IsReadOnly: true,
            IsRefLikeType: false
        );

        TypeModel model = new(
            Namespace: "Example",
            Name: "Innermost",
            Kind: TypeDeclarationKind.Class,
            Accessibility: Accessibility.Public,
            IsStatic: false,
            IsAbstract: false,
            IsSealed: false,
            IsReadOnly: false,
            IsRefLikeType: false,
            IsFileLocal: false,
            TypeParameters: default,
            ContainingTypes: new[] { outer, inner }.ToEquatableArray(),
            Attributes: default,
            Fields: default,
            Properties: default,
            Methods: default
        );

        SourceWriter writer = new();
        writer.WriteAutoGeneratedHeader();
        writer.WriteNamespace(model.Namespace);

        using (writer.WriteTypeDeclaration(model)) { }

        string expected = """
            // <auto-generated/>
            #nullable enable

            namespace Example;

            partial class Outer
            {
                readonly partial struct Inner
                {
                    partial class Innermost
                    {
                    }
                }
            }

            """;

        await Assert.That(writer.ToString()).IsEqualTo(expected);

        const string originalSource = """
            namespace Example;

            public partial class Outer
            {
                public readonly partial struct Inner
                {
                    public partial class Innermost
                    {
                    }
                }
            }
            """;

        // See the file-scoped-namespace test above for why only the type declaration (and not
        // the full header+namespace output) is compiled alongside the original source.
        SourceWriter typeOnlyWriter = new();
        using (typeOnlyWriter.WriteTypeDeclaration(model)) { }

        CompilationHelper.Compile(originalSource + "\n" + typeOnlyWriter.ToString());
    }

