    [Test]
    public async Task Should_write_a_method_signature_from_a_method_model()
    {
        ParameterModel parameter = new(
            Name: "name",
            Type: TypeRef.From(StringSymbol()),
            RefKind: RefKind.None,
            ScopedKind: ScopedKind.None,
            IsParams: false,
            DefaultValue: null,
            IsDefaultLiteral: false,
            Attributes: default
        );

        MethodModel method = new(
            Name: "DoWork",
            MethodKind: MethodKind.Ordinary,
            ReturnType: TypeRef.From(VoidSymbol()),
            ReturnRefKind: ReturnRefKind.None,
            Accessibility: Accessibility.Public,
            IsStatic: false,
            IsAbstract: true,
            IsVirtual: false,
            IsOverride: false,
            IsSealed: false,
            IsAsync: false,
            IsExtern: false,
            IsExtensionMethod: false,
            IsPartialDefinition: false,
            IsReadOnly: false,
            ExplicitInterface: null,
            ExplicitInterfaceMemberName: null,
            TypeParameters: default,
            Parameters: new[] { parameter }.ToEquatableArray(),
            Attributes: default
        );

        SourceWriter writer = new();
        writer.WriteMethodSignature(method);

        string expected = """
            public abstract void DoWork(string name);

            """;

        await Assert.That(writer.ToString()).IsEqualTo(expected);

        // The method is abstract, so no implementation is required anywhere: the generated
        // partial can add it to the type without a corresponding member in the original source.
        const string originalSource = """
            namespace Example;

            public abstract partial class Sample
            {
            }
            """;

        string generatedSource = $$"""
            partial class Sample
            {
                {{writer}}
            }
            """;

        CompilationHelper.Compile(originalSource + "\n" + generatedSource);
    }

    [Test]
    public async Task Should_render_default_parameter_values()
    {
        ParameterModel[] parameters =
        [
            new ParameterModel(
                Name: "flag",
                Type: TypeRef.From(BoolSymbol()),
                RefKind: RefKind.None,
                ScopedKind: ScopedKind.None,
                IsParams: false,
                DefaultValue: ConstantValue.ForPrimitive(true),
                IsDefaultLiteral: false,
                Attributes: default
            ),
            new ParameterModel(
                Name: "text",
                Type: TypeRef.From(StringSymbol()),
                RefKind: RefKind.None,
                ScopedKind: ScopedKind.None,
                IsParams: false,
                DefaultValue: ConstantValue.ForString("a\"b"),
                IsDefaultLiteral: false,
                Attributes: default
            ),
            new ParameterModel(
                Name: "count",
                Type: TypeRef.From(LongSymbol()),
                RefKind: RefKind.None,
                ScopedKind: ScopedKind.None,
                IsParams: false,
                DefaultValue: ConstantValue.ForPrimitive(5L),
                IsDefaultLiteral: false,
                Attributes: default
            ),
            new ParameterModel(
                Name: "value",
                Type: TypeRef.From(IntSymbol()),
                RefKind: RefKind.None,
                ScopedKind: ScopedKind.None,
                IsParams: false,
                // ParameterModel.GetDefaultValue always returns ConstantValue.ForNull for a value
                // type's `= default`; DefaultValue is null only when there is no default at all.
                DefaultValue: ConstantValue.ForNull(TypeRef.From(IntSymbol())),
                IsDefaultLiteral: true,
                Attributes: default
            ),
        ];

        // Accessibility.NotApplicable renders no keyword, matching an interface member, which is
        // the simplest declaration-only (no body) shape that doesn't also require "abstract",
        // "extern" or "partial" on the method itself.
        MethodModel method = new(
            Name: "DoWork",
            MethodKind: MethodKind.Ordinary,
            ReturnType: TypeRef.From(VoidSymbol()),
            ReturnRefKind: ReturnRefKind.None,
            Accessibility: Accessibility.NotApplicable,
            IsStatic: false,
            IsAbstract: false,
            IsVirtual: false,
            IsOverride: false,
            IsSealed: false,
            IsAsync: false,
            IsExtern: false,
            IsExtensionMethod: false,
            IsPartialDefinition: false,
            IsReadOnly: false,
            ExplicitInterface: null,
            ExplicitInterfaceMemberName: null,
            TypeParameters: default,
            Parameters: parameters.ToEquatableArray(),
            Attributes: default
        );

        SourceWriter writer = new();
        writer.WriteMethodSignature(method);

        string expected = """
            void DoWork(bool flag = true, string text = "a\"b", long count = 5L, int value = default);

            """;

        await Assert.That(writer.ToString()).IsEqualTo(expected);

        const string originalSource = """
            namespace Example;

            public partial interface ISample
            {
            }
            """;

        string generatedSource = $$"""
            partial interface ISample
            {
                {{writer}}
            }
            """;

        CompilationHelper.Compile(originalSource + "\n" + generatedSource);
    }

    [Test]
    public async Task Should_render_a_negative_enum_default_with_parentheses()
    {
        const string enumSource = """
            public enum Sign
            {
                Negative = -1,
                Positive = 1,
            }
            """;

        TypeRef signType = TypeRef.From(CompilationHelper.GetNamedTypeSymbol(enumSource, "Sign"));

        ParameterModel parameter = new(
            Name: "sign",
            Type: signType,
            RefKind: RefKind.None,
            ScopedKind: ScopedKind.None,
            IsParams: false,
            DefaultValue: ConstantValue.ForEnum(signType, -1),
            IsDefaultLiteral: false,
            Attributes: default
        );

        MethodModel method = new(
            Name: "DoWork",
            MethodKind: MethodKind.Ordinary,
            ReturnType: TypeRef.From(VoidSymbol()),
            ReturnRefKind: ReturnRefKind.None,
            Accessibility: Accessibility.NotApplicable,
            IsStatic: false,
            IsAbstract: false,
            IsVirtual: false,
            IsOverride: false,
            IsSealed: false,
            IsAsync: false,
            IsExtern: false,
            IsExtensionMethod: false,
            IsPartialDefinition: false,
            IsReadOnly: false,
            ExplicitInterface: null,
            ExplicitInterfaceMemberName: null,
            TypeParameters: default,
            Parameters: new[] { parameter }.ToEquatableArray(),
            Attributes: default
        );

        SourceWriter writer = new();
        writer.WriteMethodSignature(method);

        // Without the fix this renders "(global::Sign)-1", which the compiler parses as
        // "(global::Sign) - 1" (subtraction), not a cast, and fails to compile (CS0119).
        string expected = """
            void DoWork(global::Sign sign = (global::Sign)(-1));

            """;

        await Assert.That(writer.ToString()).IsEqualTo(expected);

        const string originalSource = """
            public enum Sign
            {
                Negative = -1,
                Positive = 1,
            }

            public partial interface ISample
            {
            }
            """;

        string generatedSource = $$"""
            partial interface ISample
            {
                {{writer}}
            }
            """;

        CompilationHelper.Compile(originalSource + "\n" + generatedSource);
    }

    [Test]
    public async Task Should_render_NaN_and_infinity_default_values()
    {
        const string source = """
            public interface ISample
            {
                void DoWork(float f1 = float.NaN, float f2 = float.PositiveInfinity, double d1 = double.NegativeInfinity);
            }
            """;

        IMethodSymbol methodSymbol = CompilationHelper
            .GetNamedTypeSymbol(source, "ISample")
            .GetMembers("DoWork")
            .OfType<IMethodSymbol>()
            .Single();

        MethodModel method = new(
            Name: "DoWork",
            MethodKind: MethodKind.Ordinary,
            ReturnType: TypeRef.From(VoidSymbol()),
            ReturnRefKind: ReturnRefKind.None,
            Accessibility: Accessibility.NotApplicable,
            IsStatic: false,
            IsAbstract: false,
            IsVirtual: false,
            IsOverride: false,
            IsSealed: false,
            IsAsync: false,
            IsExtern: false,
            IsExtensionMethod: false,
            IsPartialDefinition: false,
            IsReadOnly: false,
            ExplicitInterface: null,
            ExplicitInterfaceMemberName: null,
            TypeParameters: default,
            Parameters: methodSymbol.Parameters.Select(ParameterModel.From).ToEquatableArray(),
            Attributes: default
        );

        SourceWriter writer = new();
        writer.WriteMethodSignature(method);

        // Without the fix, ToString("R") renders these as "NaNf" / "Infinityf" / "-Infinityd",
        // none of which are valid C# tokens.
        string expected = """
            void DoWork(float f1 = float.NaN, float f2 = float.PositiveInfinity, double d1 = double.NegativeInfinity);

            """;

        await Assert.That(writer.ToString()).IsEqualTo(expected);

        const string originalSource = """
            namespace Example;

            public partial interface ISample2
            {
            }
            """;

        string generatedSource = $$"""
            partial interface ISample2
            {
                {{writer}}
            }
            """;

        CompilationHelper.Compile(originalSource + "\n" + generatedSource);
    }

    [Test]
    public async Task Should_omit_the_where_clause_for_an_override()
    {
        const string source = """
            public class Base
            {
                public virtual void Generic<T>(T value) where T : class
                {
                }
            }

            public class Derived : Base
            {
                public override void Generic<T>(T value)
                {
                }
            }
            """;

        IMethodSymbol methodSymbol = CompilationHelper
            .GetNamedTypeSymbol(source, "Derived")
            .GetMembers("Generic")
            .OfType<IMethodSymbol>()
            .Single();

        // The override's own type parameter still reports the base member's constraint (it is
        // inherited, not re-declared), which is exactly what makes writing it back out illegal.
        await Assert.That(methodSymbol.TypeParameters[0].HasReferenceTypeConstraint).IsTrue();

        MethodModel method = MethodModel.From(methodSymbol);

        SourceWriter writer = new();
        writer.WriteMethodSignature(method);

        // Without the fix this renders a "where T : class" clause, which is a compile error
        // (CS0460) on an override.
        string expected = """
            public override void Generic<T>(T value);

            """;

        await Assert.That(writer.ToString()).IsEqualTo(expected);

        const string originalSource = """
            public abstract class Base2
            {
                public abstract void Generic<T>(T value) where T : class;
            }

            public partial class Derived2 : Base2
            {
            }
            """;

        // WriteMethodSignature never writes a body (out of scope for this API); the trailing
        // ";" is swapped for "{ }" only so the override below has the body a non-abstract
        // override requires to compile.
        string signature = writer.ToString().TrimEnd();
        string signatureWithBody = signature[..^1] + " { }";

        string generatedSource = $$"""
            partial class Derived2
            {
                {{signatureWithBody}}
            }
            """;

        CompilationHelper.Compile(originalSource + "\n" + generatedSource);
    }

    [Test]
    public async Task Should_omit_the_where_clause_for_an_explicit_interface_implementation()
    {
        const string source = """
            public interface IGeneric
            {
                void Generic<T>(T value) where T : class;
            }

            public class Impl : IGeneric
            {
                void IGeneric.Generic<T>(T value)
                {
                }
            }
            """;

        IMethodSymbol methodSymbol = CompilationHelper
            .GetNamedTypeSymbol(source, "Impl")
            .GetMembers()
            .OfType<IMethodSymbol>()
            .Single(candidate =>
                candidate.MethodKind == MethodKind.ExplicitInterfaceImplementation
            );

        await Assert.That(methodSymbol.TypeParameters[0].HasReferenceTypeConstraint).IsTrue();

        MethodModel method = MethodModel.From(methodSymbol);

        SourceWriter writer = new();
        writer.WriteMethodSignature(method);

        // Without the fix this renders a "where T : class" clause, which is a compile error
        // (CS0460) on an explicit interface implementation.
        string expected = """
            void global::IGeneric.Generic<T>(T value);

            """;

        await Assert.That(writer.ToString()).IsEqualTo(expected);

        const string originalSource = """
            public interface IGeneric2
            {
                void Generic<T>(T value) where T : class;
            }

            public partial class Impl2 : IGeneric2
            {
            }
            """;

        string signature = writer.ToString().TrimEnd();
        string signatureWithBody = signature[..^1].Replace("IGeneric.", "IGeneric2.") + " { }";

        string generatedSource = $$"""
            partial class Impl2
            {
                {{signatureWithBody}}
            }
            """;

        CompilationHelper.Compile(originalSource + "\n" + generatedSource);
    }

