    [Test]
    public async Task Should_prefix_the_first_parameter_with_this_for_an_extension_method()
    {
        const string source = """
            public static partial class Extensions
            {
                public static partial void DoWork(this string value, int count);
                public static partial void DoWork(this string value, int count) { }
            }
            """;

        IMethodSymbol methodSymbol = CompilationHelper
            .GetNamedTypeSymbol(source, "Extensions")
            .GetMembers("DoWork")
            .OfType<IMethodSymbol>()
            .Single(candidate => candidate.IsPartialDefinition);

        await Assert.That(methodSymbol.IsExtensionMethod).IsTrue();

        MethodModel method = MethodModel.From(methodSymbol);

        SourceWriter writer = new();
        writer.WriteMethodSignature(method);

        // Without the fix, IsExtensionMethod is ignored and "this " is never written, so the
        // parameter list below would read "(string value, int count)".
        string expected = """
            public static partial void DoWork(this string value, int count);

            """;

        await Assert.That(writer.ToString()).IsEqualTo(expected);

        const string originalSource = """
            public static partial class Extensions2
            {
                public static partial void DoWork(this string value, int count)
                {
                }
            }
            """;

        string generatedSource = $$"""
            partial class Extensions2
            {
                {{writer}}
            }
            """;

        CompilationHelper.Compile(originalSource + "\n" + generatedSource);
    }

