    [Test]
    public async Task Should_write_a_partial_part_of_a_variant_interface_that_compiles_with_the_original()
    {
        const string originalSource = "public partial interface IFoo<out T> { }";

        INamedTypeSymbol symbol = CompilationHelper.GetNamedTypeSymbol(originalSource, "IFoo`1");
        TypeModel model = TypeModel.From(symbol);

        SourceWriter writer = new();

        using (writer.WriteTypeDeclaration(model)) { }

        await Assert.That(writer.ToString()).Contains("partial interface IFoo<out T>");

        // CS1067 (partial declarations must have the same variance) would surface as an error here.
        CompilationHelper.Compile(originalSource + "\n" + writer.ToString());
    }

    [Test]
    public async Task Should_reject_a_variant_method_type_parameter_and_leave_the_writer_empty()
    {
        const string source = "public interface ISample { void M<T>(); }";

        IMethodSymbol methodSymbol = CompilationHelper
            .GetNamedTypeSymbol(source, "ISample")
            .GetMembers("M")
            .OfType<IMethodSymbol>()
            .Single();
        MethodModel model = MethodModel.From(methodSymbol);
        MethodModel variant = model with
        {
            TypeParameters = model
                .TypeParameters.Select(parameter => parameter with { Variance = VarianceKind.Out })
                .ToEquatableArray(),
        };
        SourceWriter writer = new();

        await Assert.That(() => writer.WriteMethodSignature(variant)).Throws<ArgumentException>();
        await Assert.That(writer.ToString()).IsEqualTo(string.Empty);
    }

    [Test]
    public async Task Should_write_a_method_signature_with_ref_return_and_various_parameter_shapes()
    {
        const string source = """
            public interface ISample
            {
                ref int GetValue(scoped ref int input, char c = 'x', decimal amount = 1.5m, float ratio = 1.5f, params int[] extra);
            }
            """;

        IMethodSymbol methodSymbol = CompilationHelper
            .GetNamedTypeSymbol(source, "ISample")
            .GetMembers("GetValue")
            .OfType<IMethodSymbol>()
            .Single();

        MethodModel method = new(
            Name: "GetValue",
            MethodKind: MethodKind.Ordinary,
            ReturnType: TypeRef.From(methodSymbol.ReturnType),
            ReturnRefKind: methodSymbol.ReturnsByRef ? ReturnRefKind.Ref : ReturnRefKind.None,
            Accessibility: Accessibility.NotApplicable,
            IsStatic: false,
            IsAbstract: false,
            IsVirtual: false,
            IsOverride: false,
            IsSealed: false,
            IsAsync: false,
            IsExtern: false,
            IsExtensionMethod: false,
            IsPartialDefinition: false,
            IsReadOnly: false,
            ExplicitInterface: null,
            ExplicitInterfaceMemberName: null,
            TypeParameters: default,
            Parameters: methodSymbol.Parameters.Select(ParameterModel.From).ToEquatableArray(),
            Attributes: default
        );

        SourceWriter writer = new();
        writer.WriteMethodSignature(method);

        string expected = """
            ref int GetValue(scoped ref int input, char c = 'x', decimal amount = 1.5m, float ratio = 1.5f, params int[] extra);

            """;

        await Assert.That(writer.ToString()).IsEqualTo(expected);

        const string originalSource = """
            namespace Example;

            public partial interface ISample2
            {
            }
            """;

        string generatedSource = $$"""
            partial interface ISample2
            {
                {{writer}}
            }
            """;

        CompilationHelper.Compile(originalSource + "\n" + generatedSource);
    }

    [Test]
    public async Task Should_keep_override_on_an_abstract_override_method()
    {
        MethodModel method = new(
            Name: "M",
            MethodKind: MethodKind.Ordinary,
            ReturnType: TypeRef.From(VoidSymbol()),
            ReturnRefKind: ReturnRefKind.None,
            Accessibility: Accessibility.Public,
            IsStatic: false,
            IsAbstract: true,
            IsVirtual: false,
            IsOverride: true,
            IsSealed: false,
            IsAsync: false,
            IsExtern: false,
            IsExtensionMethod: false,
            IsPartialDefinition: false,
            IsReadOnly: false,
            ExplicitInterface: null,
            ExplicitInterfaceMemberName: null,
            TypeParameters: default,
            Parameters: default,
            Attributes: default
        );

        SourceWriter writer = new();
        writer.WriteMethodSignature(method);

        await Assert.That(writer.ToString()).IsEqualTo("public abstract override void M();\n");
    }

    private static ITypeSymbol StringSymbol()
    {
        return FieldType("string");
    }

    private static ITypeSymbol BoolSymbol()
    {
        return FieldType("bool");
    }

    private static ITypeSymbol IntSymbol()
    {
        return FieldType("int");
    }

    private static ITypeSymbol LongSymbol()
    {
        return FieldType("long");
    }

    private static ITypeSymbol VoidSymbol()
    {
        return CompilationHelper
            .Compile("class C { void F() { } }")
            .GetTypeByMetadataName("C")!
            .GetMembers("F")
            .OfType<IMethodSymbol>()
            .Single()
            .ReturnType;
    }

    private static ITypeSymbol FieldType(string typeName)
    {
        return CompilationHelper
            .Compile($"class C {{ {typeName} F; }}")
            .GetTypeByMetadataName("C")!
            .GetMembers("F")
            .OfType<IFieldSymbol>()
            .Single()
            .Type;
    }
}
